    ,sample_info.full_link_all as full_link_all
    -- recall stage
    ,d.recall_info as recall_info
    ,d.recall_info.from_organic as from_organic
    ,d.recall_info.from_ads as from_ads
    ,d.recall_info.strategies as recall_strategies
    ,d.recall_info.score as recall_score
