    ,d.rank_info.broad_pcvr as rank_broad_pcr
    -- ,d.rank_info.relevance_score as rank_relevance_score
    ,d.rank_info.ecpm as rank_ecpm
    ,d.rank_info.ecpm_weight as rank_ecpm_weight
    ,d.rank_info.estimated_gmv as rank_estimated_gmv
    ,d.rank_info.rcmd_rank_scores as rank_rcmd_rank_scores
    -- mixrank stage
    ,d.mixrank_info as mixrank_info
