    and t.country in (${grass_region})
;

--sql_divide_splitter--
insert overwrite
    srdi_mart.dwd_sr_data_warehouse_rcmd_unify_full_link_log_1h partition (
        regional_date = ${regional_date}
        ,regional_hour = ${regional_hour}
        ,country = ${grass_region}
    )
select
    -- common fields
    request_id
    ,session_id
    ,user_id
    ,entrance
    ,ab_sign
    ,ads_id as ads_id
    ,item_id as item_id
    ,shop_id as shop_id
    ,item_type
    -- status
    ,if (recall_info is not null, true, false) as is_recall
    ,if (prerank_info is not null, true, false) as is_prerank
    ,if (rank_info is not null, true, false) as is_rank
    ,is_cached
    ,if (mixrank_info is not null, true, false) as is_mixrank
    ,if (final_stage = 'DISPATCH', true, false) as is_dispatch
    ,is_sampled
    -- recall stage
    ,case
        when from_organic = true and from_ads = true then 3
        when from_ads = true then 1
        when from_organic = true then 2
        else 0
    end as recall_type
    ,transform (recall_strategies, x -> cast(x.queue_id as int)) as recall_queues
    ,transform (recall_strategies, x -> cast(x.score as float)) as queue_scores
    ,roi_revert_reason as ads_info_api_error
    ,remove_reason as recall_remove_reason
    -- prerank stage
    ,prerank_score
    ,prerank_position
    ,prerank_pctr
    ,prerank_pcr
    ,remove_reason as prerank_remove_reason
    -- rank stage
    ,rank_score
    ,rank_position
    ,item_price_v2 as rank_item_price
    ,rank_pctr
    ,rank_pcr
    ,rank_broad_pcr
    ,rank_ecpm
    ,rank_ecpm_weight
    ,rank_estimated_gmv
    ,roi_revert_reason as bidding_api_error
    ,remove_reason as rank_remove_reason
    -- mixrank stage
    ,mixrank_score
    ,mixrank_position
    ,item_price_v2 as mixrank_item_price
    ,mixrank_pctr
    ,mixrank_pcr
    ,mixrank_broad_pcr
    ,mixrank_ecpm
    ,mixrank_ecpm_weight
    ,mixrank_estimated_gmv
    ,mixrank_porg
    ,roi_revert_reason as deduction_api_error
    ,remove_reason as mixrank_remove_reason
    -- dispatch stage
    ,dispatch_position
    -- virtual item
    ,ctx_item_type as ctx_item_type
    ,ritem_id
    ,rshop_id
    ,rmodel_id
    ,null as vmodel_id -- not available now
    -- ads ext
    ,ads_recall_ext
    ,ads_info_ext
    ,ads_bid_ext
    ,ads_deduct_ext
    --new column
    ,cache_request_id
    ,ads_entrance
    ,prerank_fusion_score
    ,prerank_ecpm
    ,prerank_ecpm_weight
    ,final_stage
    ,full_link_all
    ,prerank_p0_order
    ,prerank_p0_click
    ,to_json(prerank_rcmd_rank_scores) as prerank_rcmd_rank_scores
    ,to_json(rank_rcmd_rank_scores) as rank_rcmd_rank_scores
    ,to_json(mixrank_rcmd_rank_scores) as mixrank_rcmd_rank_scores
    ,rshop_id_v2
from unify_fll_rcmd_parse_${grass_region_without_quote}
;
